package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Attributes;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.Tag;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.select.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class Element_html_TriageGen1Test {

    private Element element;

    @Before
    public void setUp() {
        Tag tag = new Tag(Tag.valueOf("div"));
        Attributes attributes = new Attributes();
        element = new Element(tag, "", attributes);
    }

    @Test
    public void testHtmlWithEmptyElement() {
        assertEquals("", element.html());
    }

    @Test
    public void testHtmlWithText() {
        element.text("Hello, World!");
        assertEquals("Hello, World!", element.html());
    }

    @Test
    public void testHtmlWithNestedElements() {
        Element child = new Element(Tag.valueOf("span"), "", new Attributes());
        child.text("Nested Text");
        element.appendChild(child);
        assertEquals("<span>Nested Text</span>", element.html());
    }

    @Test
    public void testHtmlWithAttributes() {
        element.attr("class", "test-class");
        assertEquals("<div class=\"test-class\"></div>", element.html());
    }

    @Test
    public void testHtmlWithSelfClosingTag() {
        Tag tag = new Tag(Tag.valueOf("img"));
        Element imgElement = new Element(tag, "", new Attributes());
        imgElement.attr("src", "image.jpg");
        assertEquals("<img src=\"image.jpg\" />", imgElement.html());
    }

    @Test
    public void testHtmlWithMultipleAttributes() {
        element.attr("class", "test-class");
        element.attr("id", "test-id");
        assertEquals("<div class=\"test-class\" id=\"test-id\"></div>", element.html());
    }

    @Test
    public void testHtmlWithChildrenAndAttributes() {
        Element child = new Element(Tag.valueOf("span"), "", new Attributes());
        child.text("Span Text");
        element.appendChild(child);
        element.attr("class", "parent-class");
        assertEquals("<div class=\"parent-class\"><span>Span Text</span></div>", element.html());
    }

    @Test
    public void testHtmlWithNestedChildren() {
        Element child1 = new Element(Tag.valueOf("span"), "", new Attributes());
        child1.text("Child 1");
        Element child2 = new Element(Tag.valueOf("span"), "", new Attributes());
        child2.text("Child 2");
        element.appendChild(child1);
        element.appendChild(child2);
        assertEquals("<div><span>Child 1</span><span>Child 2</span></div>", element.html());
    }

    @Test
    public void testHtmlWithPrepend() {
        Element child = new Element(Tag.valueOf("span"), "", new Attributes());
        child.text("Prepended Text");
        element.prepend(child);
        assertEquals("<div><span>Prepended Text</span></div>", element.html());
    }

    @Test
    public void testHtmlWithAppend() {
        Element child = new Element(Tag.valueOf("span"), "", new Attributes());
        child.text("Appended Text");
        element.append(child);
        assertEquals("<div><span>Appended Text</span></div>", element.html());
    }

    @Test
    public void testHtmlWithEmpty() {
        element.appendText("Some Text");
        element.empty();
        assertEquals("<div></div>", element.html());
    }

    @Test
    public void testHtmlWithNestedEmpty() {
        Element child = new Element(Tag.valueOf("span"), "", new Attributes());
        child.text("Text");
        element.appendChild(child);
        child.empty();
        assertEquals("<div><span></span></div>", element.html());
    }

    @Test
    public void testHtmlWithBefore() {
        Element newElement = new Element(Tag.valueOf("p"), "", new Attributes());
        newElement.text("Before Text");
        element.before(newElement);
        assertEquals("<p>Before Text</p><div></div>", newElement.parent().html());
    }

    @Test
    public void testHtmlWithAfter() {
        Element newElement = new Element(Tag.valueOf("p"), "", new Attributes());
        newElement.text("After Text");
        element.after(newElement);
        assertEquals("<div></div><p>After Text</p>", newElement.parent().html());
    }
}
